const REVOLT_LOCATIONS={meerut:{title:"Meerut — Spark of the Uprising",meta:"Date: May 10, 1857 | Region: Western Uttar Pradesh",leader:"Sepoys of 3rd Native Cavalry",details:"85 sepoys who refused to use grease cartridges were court-martialed and jailed. On May 10, fellow sepoys revolted, freed their comrades, killed British officers, and marched towards Delhi."},delhi:{title:"Delhi — Capital & Imperial Symbol",meta:"Date: May 11 – September 20, 1857 | Leader: Bahadur Shah Zafar & Bakht Khan",leader:"Emperor Bahadur Shah II & General Bakht Khan",details:"Rebellious sepoys proclaimed Mughal Emperor Bahadur Shah II as Shahenshah-e-Hindustan. Commander Bakht Khan managed the city defense until British forces besieged and recaptured Delhi after fierce fighting."},kanpur:{title:"Kanpur — Nana Saheb & Tatya Tope",meta:"Date: June 5 – December 1857 | Region: Central UP",leader:"Nana Saheb, Tatya Tope, Azimullah Khan",details:"Nana Saheb, adopted son of Peshwa Baji Rao II, led the revolt after being denied pension. Tatya Tope provided exceptional military leadership during battles against General Havelock and Campbell."},lucknow:{title:"Lucknow — Siege of Residency",meta:"Date: May 30, 1857 – March 1858 | Region: Awadh",leader:"Begum Hazrat Mahal & Ahmadullah Shah",details:"Begum Hazrat Mahal proclaimed her young son Birjis Qadr as Nawab of Awadh. Peasants, zamindars, and sepoys besieged the British Residency for months until Colin Campbell suppressed the city."},jhansi:{title:"Jhansi — Valor of Rani Lakshmibai",meta:"Date: June 1857 – June 1858 | Region: Bundelkhand",leader:"Rani Lakshmibai",details:"Rani Lakshmibai fiercely defended Jhansi against Sir Hugh Rose's siege. She escaped to Gwalior, captured the fort alongside Tatya Tope, and fought until her heroic death at Kotah-ki-Serai."},bihar:{title:"Jagdishpur (Bihar) — Kunwar Singh",meta:"Date: July 1857 – April 1858 | Region: Shahabad, Bihar",leader:"Kunwar Singh & Amar Singh",details:"The 80-year-old Rajput zamindar Kunwar Singh led brilliant guerrilla campaigns across Bihar and Eastern UP, defeating British detachments multiple times before succumbing to wounds."}},TIMELINE_DATA=[{date:"March 29, 1857",event:"Mangal Pandey attacks British officers at Barrackpore parade ground."},{date:"May 10, 1857",event:"Sepoy Mutiny erupts in Meerut; sepoys march to Delhi."},{date:"May 11, 1857",event:"Bahadur Shah Zafar declared Emperor of India in Delhi."},{date:"June 1857",event:"Revolt spreads across Kanpur, Lucknow, Jhansi, Allahabad, and Bihar."},{date:"September 20, 1857",event:"British forces recapture Delhi; Bahadur Shah Zafar arrested."},{date:"June 18, 1858",event:"Rani Lakshmibai martyred fighting at Gwalior."},{date:"November 1, 1858",event:"Queen Victoria's Proclamation transfers India's government from East India Company to British Crown."}],LEADERS_DATA=[{name:"Rani Lakshmibai",role:"Queen of Jhansi",desc:"Symbol of armed struggle who led troops from the front line."},{name:"Nana Saheb",role:"Peshwa Leader of Kanpur",desc:"Reclaimed Peshwaship and led the resistance in Kanpur."},{name:"Tatya Tope",role:"Military Strategist",desc:"Master of guerrilla warfare across Central India and Bundelkhand."},{name:"Begum Hazrat Mahal",role:"Begum of Awadh",desc:"Rallied rural and urban forces in defense of Lucknow."},{name:"Kunwar Singh",role:"Zamindar of Jagdishpur",desc:"80-year-old warrior who routed British forces in Bihar."},{name:"Mangal Pandey",role:"Sepoy of 34th Bengal Native Infantry",desc:"The initial spark whose defiance at Barrackpore inspired thousands."}];document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("loc-title"),a=document.getElementById("loc-meta"),r=document.getElementById("loc-body"),t=document.getElementById("r1857-timeline"),n=document.getElementById("r1857-leaders-grid");window.selectLocation=function(t){const n=REVOLT_LOCATIONS[t];n&&e&&(e.textContent=n.title,a.textContent=n.meta,r.innerHTML=`\n            <p><strong>Primary Leader:</strong> ${n.leader}</p>\n            <p>${n.details}</p>\n        `)},t&&(t.innerHTML=TIMELINE_DATA.map(e=>`\n            <div class="r1857-tl-item">\n                <div class="r1857-tl-year">${e.date}</div>\n                <div style="font-size:1.05rem;">${e.event}</div>\n            </div>\n        `).join("")),n&&(n.innerHTML=LEADERS_DATA.map(e=>`\n            <div class="r1857-leader-card">\n                <h3 style="margin:0 0 0.25rem; font-family:'Playfair Display', serif;">${e.name}</h3>\n                <div style="color:var(--r1857-secondary); font-size:0.875rem; font-weight:600; margin-bottom:0.75rem;">${e.role}</div>\n                <p style="margin:0; font-size:0.9rem; color:var(--r1857-muted);">${e.desc}</p>\n            </div>\n        `).join(""))});